16	    if (!currentGame) return notFound();
17	    const players = await outcomeService.getAdminByGameDay(currentGame.id);
18	    const playersWithGames = await Promise.all(
19	        players.map(async (player) => ({
20	            ...player,
21	            gamesPlayed: await outcomeService.getGamesPlayedByPlayer(player.playerId, 0),
