39	export const PickerForm = ({
40	    gameDay,
41	    players,
42	    submitPicker,
43	    setGameEnabled,
44	}: PickerFormProps) => {
45	    const router = useRouter();
46	    const eligiblePlayers = useMemo(
47	        () => players.filter((player) => player.response === 'Yes'),
48	        [players],
49	    );
50	    const [sortKey, setSortKey] = useState<SortKey>('responseTime');
51	    const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
52	    const [selectedIds, setSelectedIds] = useState<number[]>(() => buildDefaultSelection(eligiblePlayers));
53	    const [isSubmitting, setIsSubmitting] = useState(false);
54	    const [reason, setReason] = useState('');
55	    const [isSettingEnabled, setIsSettingEnabled] = useState(false);
56	
57	    const sortedPlayers = useMemo(() => {
58	        const data = [...eligiblePlayers];
59	        data.sort((a, b) => {
60	            switch (sortKey) {
61	                case 'name':
62	                    return compareNullableString(a.player.name, b.player.name, sortDirection);
63	                case 'responseTime':
64	                    return compareNullableNumber(a.responseInterval, b.responseInterval, sortDirection);
65	                case 'gamesPlayed':
66	                    return compareNullableNumber(a.gamesPlayed, b.gamesPlayed, sortDirection);
67	                /* v8 ignore next 2 -- SortKey is a union type; default is unreachable */
68	                default:
69	                    return 0;
70	            }
71	        });
72	        return data;
73	    }, [eligiblePlayers, sortKey, sortDirection]);
74	
75	    const selectedIdSet = useMemo(() => new Set(selectedIds), [selectedIds]);
76	    const filteredSelectedCount = useMemo(() => (
77	        eligiblePlayers.reduce((acc, row) => (selectedIdSet.has(row.playerId) ? acc + 1 : acc), 0)
78	    ), [eligiblePlayers, selectedIdSet]);
79	
80	    const allSelected = eligiblePlayers.length > 0 && filteredSelectedCount === eligiblePlayers.length;
81	    const someSelected = filteredSelectedCount > 0 && !allSelected;
82	    const hasSelection = filteredSelectedCount > 0;
83	
84	    const selectedPlayers = useMemo(() => (
85	        eligiblePlayers.filter((player) => selectedIdSet.has(player.playerId))
86	    ), [eligiblePlayers, selectedIdSet]);
87	
88	    const toggleSelectAll = (checked: boolean) => {
89	        if (checked) {
90	            setSelectedIds((prev) => Array.from(new Set([
91	                ...prev,
92	                ...eligiblePlayers.map((player) => player.playerId),
93	            ])));
94	            return;
95	        }
96	
97	        const eligibleIdSet = new Set(eligiblePlayers.map((player) => player.playerId));
98	        setSelectedIds((prev) => prev.filter((id) => !eligibleIdSet.has(id)));
99	    };
100	
101	    const toggleSelectPlayer = (playerId: number, checked: boolean) => {
102	        setSelectedIds((prev) => {
103	            if (checked) {
104	                /* v8 ignore next -- defensive guard against duplicate adds; normal checkbox behaviour never fires checked=true when already selected */
105	                return prev.includes(playerId) ? prev : [...prev, playerId];
106	            }
107	            return prev.filter((id) => id !== playerId);
108	        });
109	    };
110	
111	    const handleSort = (key: SortKey) => {
112	        if (key === sortKey) {
113	            setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
114	            return;
115	        }
116	        setSortKey(key);
117	        setSortDirection('asc');
118	    };
119	
120	    const getSortIcon = (key: SortKey) => {
121	        if (key !== sortKey) return <IconSelector size={14} />;
122	        return sortDirection === 'asc' ? <IconChevronUp size={14} /> : <IconChevronDown size={14} />;
123	    };
124	
125	    const renderSortHeader = (label: string, key: SortKey) => (
126	        <UnstyledButton
127	            type="button"
128	            onClick={() => handleSort(key)}
129	            aria-label={`Sort by ${label}`}
130	        >
131	            <Group gap={6} wrap="nowrap">
132	                <Text span>{label}</Text>
133	                {getSortIcon(key)}
134	            </Group>
135	        </UnstyledButton>
136	    );
137	
138	    const handleSubmit = async () => {
139	        /* v8 ignore next 7 -- Pick sides button is disabled when !hasSelection; guard is a defensive backstop */
140	        if (!hasSelection) {
141	            notifications.show({
142	                color: 'yellow',
143	                title: 'No players selected',
144	                message: 'Select at least one player before submitting.',
145	            });
146	            return;
147	        }
148	
149	        const notificationId = 'picker-submit';
150	        notifications.show({
151	            id: notificationId,
152	            loading: true,
153	            title: 'Submitting picker',
154	            message: 'Submitting selected players...',
155	            autoClose: false,
156	            withCloseButton: false,
157	        });
158	
159	        setIsSubmitting(true);
160	        try {
161	            await submitPicker(
162	                selectedPlayers.map((player) => ({
163	                    playerId: player.playerId,
164	                })),
165	            );
166	            notifications.update({
167	                id: notificationId,
168	                color: 'teal',
169	                title: 'Selection submitted',
170	                message: `${selectedPlayers.length} players submitted.`,
171	                icon: <IconCheck size={config.notificationIconSize} />,
172	                loading: false,
173	                autoClose: config.notificationAutoClose,
174	            });
175	
176	            router.push(`/footy/game/${gameDay.id}`);
177	        } catch (err) {
178	            const errorMessage = err instanceof Error ? err.message : 'Failed to submit selection';
179	            notifications.update({
180	                id: notificationId,
181	                color: 'red',
182	                title: 'Error',
183	                message: errorMessage,
184	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
185	                loading: false,
186	                autoClose: false,
187	                withCloseButton: true,
188	            });
189	        } finally {
190	            setIsSubmitting(false);
191	        }
192	    };
193	
194	    const handleSetGameEnabled = async () => {
195	        const notificationId = 'set-enabled';
196	        notifications.show({
197	            id: notificationId,
198	            loading: true,
199	            title: 'Updating game status',
200	            message: 'Updating game status...',
201	            autoClose: false,
202	            withCloseButton: false,
203	        });
204	
205	        setIsSettingEnabled(true);
206	        try {
207	            await setGameEnabled(
208	                {
209	                    gameDayId: gameDay.id,
210	                    game: !gameDay.game,
211	                    reason: reason,
212	                },
213	            );
214	            notifications.update({
215	                id: notificationId,
216	                color: 'teal',
217	                title: gameDay.game ? 'Game cancelled' : 'Game reinstated',
218	                message: gameDay.game ? 'The game has been marked as cancelled.' : 'The game has been reinstated.',
219	                icon: <IconCheck size={config.notificationIconSize} />,
220	                loading: false,
221	                autoClose: config.notificationAutoClose,
222	            });
223	        } catch (err) {
224	            const errorMessage = err instanceof Error ? err.message : 'Failed to set game status';
225	            notifications.update({
226	                id: notificationId,
227	                color: 'red',
228	                title: 'Error',
229	                message: errorMessage,
230	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
231	                loading: false,
232	                autoClose: false,
233	                withCloseButton: true,
234	            });
235	        } finally {
236	            setIsSettingEnabled(false);
237	        }
238	    };
239	
240	    const rows = sortedPlayers.map((player) => {
241	        const playerName = getPlayerName(player);
242	
243	        return (
244	            <TableTr key={player.playerId}>
245	                <TableTd w="2.5rem">
246	                    <Checkbox
247	                        checked={selectedIdSet.has(player.playerId)}
248	                        onChange={(event) => toggleSelectPlayer(player.playerId, event.currentTarget.checked)}
249	                        aria-label={`Select ${playerName}`}
250	                    />
251	                </TableTd>
252	                <TableTd>{playerName}</TableTd>
253	                <TableTd>{formatResponseInterval(player.responseInterval ?? null)}</TableTd>
254	                <TableTd>{player.gamesPlayed}</TableTd>
255	            </TableTr>
256	        );
257	    });
258	
259	    const picker = (
260	        <>
261	            <Group justify="space-between" align="center" wrap="wrap">
262	                <Text fw={700}>Players selected ({filteredSelectedCount})</Text>
263	                <Button
264	                    type="button"
265	                    onClick={handleSubmit}
266	                    disabled={!hasSelection || isSettingEnabled}
267	                    loading={isSubmitting}
268	                    w={150}
269	                >
270	                    Pick sides
271	                </Button>
272	            </Group>
273	            <Table
274	                striped
275	                highlightOnHover
276	                withTableBorder
277	                withColumnBorders
278	                w="100%"
279	                style={{ tableLayout: 'fixed' }}
280	            >
281	                <TableThead>
282	                    <TableTr>
283	                        <TableTh w="2.5rem">
284	                            <Checkbox
285	                                checked={allSelected}
286	                                indeterminate={someSelected}
287	                                onChange={(event) => toggleSelectAll(event.currentTarget.checked)}
288	                                aria-label="Select all players"
289	                            />
290	                        </TableTh>
291	                        <TableTh aria-sort={sortKey === 'name' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
292	                            {renderSortHeader('Player', 'name')}
293	                        </TableTh>
294	                        <TableTh aria-sort={sortKey === 'responseTime' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
295	                            {renderSortHeader('Response time', 'responseTime')}
296	                        </TableTh>
297	                        <TableTh aria-sort={sortKey === 'gamesPlayed' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
298	                            {renderSortHeader('Total games played', 'gamesPlayed')}
299	                        </TableTh>
300	                    </TableTr>
301	                </TableThead>
302	                <TableTbody>{rows}</TableTbody>
303	            </Table>
304	            <Divider
305	                label="or"
306	                labelPosition="center"
307	            />
308	        </>
309	    );
310	
311	    // TODO: New game date component?
312	    return (
313	        <Stack gap="md">
314	            <Stack align="left" gap="xs">
315	                <Title order={2}>Picker</Title>
316	                <Text c="dimmed">Game {gameDay.id}: {formatDate(gameDay.date)}</Text>
317	            </Stack>
318	            {gameDay.game ? picker : null}
319	            <Group justify="space-between" align="center" wrap="wrap">
320	                <TextInput
321	                    aria-label={gameDay.game ? "Cancellation reason" : "Reinstatement reason"}
322	                    placeholder={gameDay.game ? "not enough players" : ""}
323	                    value={reason}
324	                    onChange={(event) => setReason(event.currentTarget.value)}
325	                    disabled={isSubmitting || isSettingEnabled}
326	                    flex={1}
327	                />
328	                <Button
329	                    type="button"
330	                    color={gameDay.game ? "red" : "green"}
331	                    onClick={handleSetGameEnabled}
332	                    loading={isSettingEnabled}
333	                    disabled={isSubmitting || isSettingEnabled}
334	                    w={150}
335	                >
336	                    {gameDay.game ? 'Cancel game' : 'Reinstate game'}
337	                </Button>
338	            </Group>
339	        </Stack>
340	    );
341	};
342	
343	type SortKey = 'name' | 'responseTime' | 'gamesPlayed';
344	type SortDirection = 'asc' | 'desc';
345	
346	const compareNullableNumber = (
347	    a: number | null | undefined,
348	    b: number | null | undefined,
349	    direction: SortDirection,
350	) => {
351	    if (a == null && b == null) return 0;
352	    if (a == null) return 1;
353	    if (b == null) return -1;
354	    return direction === 'asc' ? a - b : b - a;
355	};
356	
357	const compareNullableString = (
358	    a: string | null | undefined,
359	    b: string | null | undefined,
360	    direction: SortDirection,
361	) => {
362	    if (a == null && b == null) return 0;
363	    if (a == null) return 1;
364	    if (b == null) return -1;
365	    const result = a.localeCompare(b);
366	    return direction === 'asc' ? result : -result;
367	};
368	
369	const formatResponseInterval = (seconds: number | null | undefined) => {
370	    if (seconds == null) return '-';
371	    if (seconds < 60) return `${seconds}s`;
372	
373	    const minutes = Math.floor(seconds / 60);
374	    if (minutes < 60) return `${minutes}m`;
375	
376	    const hours = Math.floor(minutes / 60);
377	    const remainingMinutes = minutes % 60;
378	    if (hours < 24) {
379	        return remainingMinutes ? `${hours}h ${remainingMinutes}m` : `${hours}h`;
380	    }
381	
382	    const days = Math.floor(hours / 24);
383	    const remainingHours = hours % 24;
384	    return remainingHours ? `${days}d ${remainingHours}h` : `${days}d`;
385	};
386	
387	const getPlayerName = (row: PickerPlayerType) => row.player.name ?? `Player ${row.playerId}`;
388	
389	const buildDefaultSelection = (rows: PickerPlayerType[], maxSelected = 12) => {
390	    if (!rows.length) return [];
391	    const sorted = [...rows].sort((a, b) => {
392	        const responseCompare = compareNullableNumber(a.responseInterval, b.responseInterval, 'asc');
393	        if (responseCompare !== 0) return responseCompare;
394	        const nameCompare = compareNullableString(a.player.name, b.player.name, 'asc');
395	        if (nameCompare !== 0) return nameCompare;
396	        return a.playerId - b.playerId;
397	    });
398	    return sorted.slice(0, maxSelected).map((row) => row.playerId);
399	};
