28	export const AdminUserList = ({ users, setAdminRole }: Props) => {
29	    const [sortBy, setSortBy] = useState<keyof UserWithRole | null>('name');
30	    const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('asc');
31	    const [filter, setFilter] = useState('');
32	    const [errorMessage, setErrorMessage] = useState<string | null>(null);
33	
34	    const handleSort = (key: keyof UserWithRole) => {
35	        if (sortBy === key) {
36	            setSortOrder((prev) => (prev === 'asc' ? 'desc' : 'asc'));
37	        } else {
38	            setSortBy(key);
39	            setSortOrder('asc');
40	        }
41	    };
42	
43	    const renderSortHeader = (label: string, key: keyof UserWithRole) => (
44	        <UnstyledButton type="button" onClick={() => handleSort(key)} aria-label={`Sort by ${label}`}>
45	            <Group gap={6} wrap="nowrap">
46	                <Text span>{label}</Text>
47	                {sortBy === key ? (
48	                    sortOrder === 'asc' ?
49	                        <IconSortAscending size={16} aria-hidden="true" focusable={false} /> :
50	                        <IconSortDescending size={16} aria-hidden="true" focusable={false} />
51	                ) : null}
52	            </Group>
53	        </UnstyledButton>
54	    );
55	
56	    const toggleAdmin = async (userId: string, isAdmin: boolean) => {
57	        try {
58	            await setAdminRole(userId, isAdmin);
59	        } catch (error) {
60	            captureUnexpectedError(error, {
61	                layer: 'client',
62	                action: 'setAdminRoleAction',
63	                component: 'AdminUsersPage',
64	                route: '/footy/admin/users',
65	                extra: {
66	                    userId,
67	                    isAdmin,
68	                },
69	            });
70	            setErrorMessage('Failed to update admin status');
71	        }
72	    };
73	
74	    const filteredUsers = users?.filter((user) => {
75	        const searchTerm = filter.toLowerCase();
76	        return (
77	            user.name.toLowerCase().includes(searchTerm) ||
78	            user.email.toLowerCase().includes(searchTerm)
79	        );
80	    }) ?? [];
81	
82	    /* v8 ignore next -- filteredUsers is always an array via the nullish coalescing above; this fallback is a defensive backstop */
83	    const sortedUsers = filteredUsers ? [...filteredUsers].sort((a, b) => {
84	        if (!sortBy) return 0;
85	
86	        const aValue = String(a[sortBy] ?? '').toLowerCase();
87	        const bValue = String(b[sortBy] ?? '').toLowerCase();
88	
89	        return sortOrder === 'asc' ?
90	            aValue.localeCompare(bValue) :
91	            bValue.localeCompare(aValue);
92	    }) : [];
93	
94	    if (errorMessage) {
95	        return (
96	            <Container>
97	                <Text c="red">{errorMessage}</Text>
98	            </Container>
99	        );
100	    }
101	
102	    return (
103	        <Container size="md">
104	            <Paper w="100%" p="xl">
105	                <TextInput
106	                    label="Search users"
107	                    placeholder="Search users"
108	                    value={filter}
109	                    onChange={(event) => setFilter(event.currentTarget.value)}
110	                />
111	                <Table.ScrollContainer minWidth="100%" scrollAreaProps={{ type: 'auto' }}>
112	                    <Table mt={20} layout="fixed">
113	                        <Table.Thead>
114	                            <Table.Tr>
115	                                <Table.Th w="10rem" aria-sort={sortBy === 'name' ? (sortOrder === 'asc' ? 'ascending' : 'descending') : 'none'}>
116	                                    {renderSortHeader('Name', 'name')}
117	                                </Table.Th>
118	                                <Table.Th w="16rem" aria-sort={sortBy === 'email' ? (sortOrder === 'asc' ? 'ascending' : 'descending') : 'none'}>
119	                                    {renderSortHeader('Email', 'email')}
120	                                </Table.Th>
121	                                <Table.Th w="6rem" aria-sort={sortBy === 'role' ? (sortOrder === 'asc' ? 'ascending' : 'descending') : 'none'}>
122	                                    {renderSortHeader('Admin', 'role')}
123	                                </Table.Th>
124	                                <Table.Th w="10rem" aria-sort={sortBy === 'createdAt' ? (sortOrder === 'asc' ? 'ascending' : 'descending') : 'none'}>
125	                                    {renderSortHeader('Created', 'createdAt')}
126	                                </Table.Th>
127	                            </Table.Tr>
128	                        </Table.Thead>
129	                        <Table.Tbody>
130	                            {sortedUsers.map((user) => (
131	                                <Table.Tr key={user.email}>
132	                                    <Table.Td>
133	                                        <Anchor href={`/footy/admin/user/${encodeURIComponent(user.email)}`}>
134	                                            {user.name}
135	                                        </Anchor>
136	                                    </Table.Td>
137	                                    <Table.Td>
138	                                        <Anchor href={`/footy/admin/user/${encodeURIComponent(user.email)}`}>
139	                                            {user.email}
140	                                        </Anchor>
141	                                    </Table.Td>
142	                                    <Table.Td>
143	                                        <Switch
144	                                            checked={user.role === 'admin'}
145	                                            onChange={(event) => toggleAdmin(user.id, event.currentTarget.checked)}
146	                                            aria-label={
147	                                                user.name ?
148	                                                    `Toggle admin status for ${user.name}` :
149	                                                    `Toggle admin status for ${user.email}`
150	                                            }
151	                                            color="blue"
152	                                        />
153	                                    </Table.Td>
154	                                    <Table.Td>
155	                                        <RelativeTime date={user.createdAt} />
156	                                    </Table.Td>
157	                                </Table.Tr>
158	                            ))}
159	                        </Table.Tbody>
160	                    </Table>
161	                </Table.ScrollContainer>
162	            </Paper>
163	        </Container>
164	    );
165	};
