import { chromium } from '@playwright/test';

const viewports = [
    { name: 'mobile', width: 390, height: 900 },
    { name: 'tablet', width: 800, height: 1000 },
    { name: 'desktop', width: 1400, height: 1000 },
];

const url = 'http://localhost:6006/iframe.html?id=admin-pickerform--render&viewMode=story';

const browser = await chromium.launch();
for (const vp of viewports) {
    const page = await browser.newPage({ viewport: { width: vp.width, height: vp.height } });
    await page.goto(url, { waitUntil: 'networkidle' });
    await page.waitForSelector('text=Picker', { timeout: 15000 });
    await page.screenshot({ path: `/private/tmp/claude-501/-Volumes-Development-next-www-toastboy/9cef106a-28d4-4a58-9fd2-a89738274ad0/scratchpad/picker-${vp.name}.png`, fullPage: true });
    await page.close();
}
await browser.close();
console.log('done');

